-- =============================================================================
-- ALL 3 CLASSES + STUDENTS IMPORT (160 Students)
-- Digital University of Cambodia
-- =============================================================================

USE classroom_db;

SET FOREIGN_KEY_CHECKS = 0;
TRUNCATE TABLE resources; 
TRUNCATE TABLE assignments;
TRUNCATE TABLE attendance; 
TRUNCATE TABLE schedules;
TRUNCATE TABLE students; 
TRUNCATE TABLE teachers;
TRUNCATE TABLE subjects; 
TRUNCATE TABLE classes; 
TRUNCATE TABLE users;
SET FOREIGN_KEY_CHECKS = 1;

-- 1. CLASSES (ទាំង ៣ ថ្នាក់)

-- 2. SUBJECTS

-- 3. USERS (Admin + Teachers + Sambath + 160 Students)

-- 4. TEACHERS

-- 5. STUDENTS (161 Total)

-- 6. SCHEDULES (Class Timetables)

SELECT 'Import of All 3 Classes Completed Successfully!' AS Status;
SELECT c.class_code, c.class_name, COUNT(s.id) AS total_students FROM classes c LEFT JOIN students s ON s.class_id = c.id GROUP BY c.id;
SELECT COUNT(*) AS total_users FROM users;
